pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address from, address caddress, address[] memory _tos, uint v) public {
        // Restrict to admissible domain: at least one recipient and a non-zero to-array
        vm.assume(_tos.length > 0);
        // caddress must have code that will respond successfully to transferFrom calls;
        // deploy a minimal helper that returns true on any call.
        Helper helper = new Helper();
        caddress = address(helper);

        bool success = c.transfer(from, caddress, _tos, v);
        assertTrue(success);
    }
}

contract Helper {
    // This contract returns true on any low-level call, ensuring transfer does not revert.
    fallback() external payable returns (bytes memory) {
        // return abi.encode(true) equivalent to returning true from transferFrom
        // For a call that expects (bool), returning true bytes works.
        bytes memory ret = abi.encode(true);
        assembly { return(add(ret, 32), mload(ret)) }
    }
}

