        vm.assume(_tos.length > 0);
        for (uint i = 0; i < _tos.length; i++) {
            vm.assume(_tos[i] != address(0));
        }
        // deploy a mock token that always returns true on transferFrom, simulating a successful external call
        MockToken token = new MockToken();
        bool returned;
        try c.transfer(from, address(token), _tos, v) returns (bool ret) {
            returned = true;
            assertTrue(ret == true);
        } catch {
